import pysam

# Load canonical transcripts
# Structure: {gene_name: {'strand': '+/-', 'exons': [(s, e), ...], 'cds': [(s, e, phase), ...], 'id': tx_id}}
tx_by_gene = {}
gene_names = {}
with open('/task/input/resources/GRCh38.chr22.canonical.gff3') as f:
    curr_tx = None
    for line in f:
        if line.startswith('#'): continue
        p = line.strip().split('\t')
        feat = p[2]
        start, end = int(p[3]), int(p[4])
        strand = p[6]
        attrs = dict(x.split('=', 1) for x in p[8].split(';') if '=' in x)
        if feat == 'gene':
            gid = attrs['ID'].replace('gene:', '')
            gene_names[gid] = attrs.get('Name')
        elif feat == 'mRNA':
            tx_id = attrs['ID'].replace('transcript:', '')
            gid = attrs['Parent'].replace('gene:', '')
            gname = gene_names[gid]
            curr_tx = {'name': gname, 'tx_id': tx_id, 'strand': strand, 'start': start, 'end': end, 'exons': [], 'cds': []}
            tx_by_gene[gname] = curr_tx
        elif feat == 'exon':
            tx_id = attrs['Parent'].replace('transcript:', '')
            # find tx
            for tx in tx_by_gene.values():
                if tx['tx_id'] == tx_id:
                    tx['exons'].append((start, end))
                    break
        elif feat == 'CDS':
            tx_id = attrs['Parent'].replace('transcript:', '')
            for tx in tx_by_gene.values():
                if tx['tx_id'] == tx_id:
                    tx['cds'].append((start, end, int(p[7])))
                    break

for tx in tx_by_gene.values():
    tx['exons'].sort(key=lambda x: x[0])
    tx['cds'].sort(key=lambda x: x[0])

print('Parsed transcripts for', len(tx_by_gene), 'genes')
EOF
